struct ReadyEvent {
    Registration id = 0;
    bool readable = false, writable = false, error = false;
};
enum class PollState { events, timeout, interrupted, error };
struct ReadyBatch {
    PollState state = PollState::timeout;
    std::vector<ReadyEvent> events;
    bool woken = false;
    int error = 0;
};

class StudyReactor {
 public:
    virtual ~StudyReactor() = default;
    virtual std::optional<Registration> watch(const Socket&, unsigned interest) = 0;
    virtual bool change(Registration, unsigned interest) = 0;
    virtual bool unwatch(Registration) = 0;
    virtual bool current(Registration) const = 0;
    virtual ReadyBatch poll(int timeout_ms) = 0; // 0..1000ms, requested wait not scheduling bound.
    virtual bool wake() noexcept = 0; // Notification only; authoritative work lives elsewhere.
};

std::optional<Registration> add(Runtime::Native fd, unsigned interest) noexcept {
    if (!Runtime::native_valid(fd)) {
        return std::nullopt;
    }
    if ((interest & ~kInterestMask) != 0) {
        return std::nullopt;
    }
    if (has_fd(fd)) {
        return std::nullopt;
    }
    std::optional<RegistrationEntry>* slot = vacant();
    if (slot == nullptr) {
        return std::nullopt;
    }
    if (next_ == kInvalidRegistration) {
        return std::nullopt;
    }
    const Registration id = next_;
    // Advance one step, but never wrap back into valid ids: 0 is permanent
    // exhaustion so ids are never reused for the lifetime of this object.
    next_ = (next_ == UINT64_MAX) ? kInvalidRegistration : next_ + 1;
    slot->emplace(RegistrationEntry{id, fd, interest});
    return id;
}

bool remove(Registration id) noexcept {
    for (auto& slot : slots_) {
        if (slot.has_value() && slot->id == id) {
            slot.reset();
            return true;
        }
    }
    return false;
}

bool modify(Registration id, unsigned interest) noexcept {
    if ((interest & ~kInterestMask) != 0) {
        return false;
    }
    RegistrationEntry* entry = mutable_find(id);
    if (entry == nullptr) {
        return false;
    }
    entry->interest = interest;
    return true;
}

